  {"decl": "familyExtremal", "line": 18, "plain": "ex(n,F) = max |E(G)| over F-free G on n vertices, with sup ∅ = 0.", "standard_concept": "extremal number of a family", "matches_standard": "yes", "note": "The filter is never empty for cyclic families, since the empty graph is free."},
