 ],
 "lean_claims": [
  {"theorem": "not_erdos_180", "line": 46, "plain": "The compactness conjecture, as defined, is false."},
  {"theorem": "quantitativeCompactnessCounterexample", "line": 52, "plain": "There exist a nonempty finite family F of connected, bipartite, non-acyclic graphs and constants c>0, C≥0 such that: (a) for each F ∈ F, eventually c n^{4/3} ≤ ex(n,F); (b) for all n and all F-free G on n vertices, e(G)^16 ≤ C n^21; (c) ex(n,F)^16 ≤ C n^21 for all n; (d) the trivial facts 0 < 1/48 and 21/16 = 4/3 - 1/48; (e) F is not compact; (f) the conjecture is false."},
  {"theorem": "compactnessCounterexample_bigO", "line": 72, "plain": "There exist a nonempty finite family F of connected, bipartite, cyclic graphs and c>0 such that each member has ex(n,F) ≥ c n^{4/3} eventually, ex(n,F) = O(n^{4/3-1/48}) as n→∞, F is not compact, and the conjecture is false."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "There is a finite nonempty family F of connected bipartite graphs, each containing a cycle, with ex(n,F) = O(n^{4/3-1/48}) and ex(n,F) = Ω(n^{4/3}) for each F ∈ F; in particular no member satisfies (1), disproving the compactness conjecture."},
  {"ref": "Theorem 1.2", "plain": "There is a connected bipartite 2-degenerate graph H with ex(n,H) ≥ c n^{3/2+ε} for all large n."}
 ],
